WITH joined AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.volume,b.lastPx/10000.0 AS px,t.ma10 FROM `newzl`.`hsj_stock_hq_basic` b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate), event_rows AS (SELECT mktcode,tgtcode,bizdate,volume,px<ma10 AND LAG(px) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)>=LAG(ma10) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS occurred FROM joined), eligible AS (SELECT DISTINCT mktcode,tgtcode FROM event_rows WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 3) AND occurred IS NOT NULL), occurred AS (SELECT DISTINCT mktcode,tgtcode FROM event_rows WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 3) AND occurred=TRUE), absent AS (SELECT e.mktcode,e.tgtcode FROM eligible e LEFT ANTI JOIN occurred o ON o.mktcode=e.mktcode AND o.tgtcode=e.tgtcode) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN absent a ON a.mktcode=b.mktcode AND a.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14' AND b.volume>0;
